#!/usr/bin/env node

/**
 * Polar Webhook Verification Script
 *
 * Verifies Polar webhook signatures (Standard Webhooks headers):
 *   webhook-id, webhook-timestamp, webhook-signature ("v1,<base64>" entries, space-separated)
 *   signed content = `${webhook-id}.${webhook-timestamp}.${rawBody}` (HMAC-SHA256, base64)
 *
 * Polar has two signing keys depending on when the endpoint secret was generated:
 *   - Before 2026-09-08 00:00 UTC (or user-provided secrets): "Polar HMAC",
 *     key = UTF-8 bytes of the full secret string.
 *   - Generated by Polar on/after that instant: Standard Webhooks,
 *     key = base64-decoded secret (after stripping a "whsec_" prefix).
 * Like Polar SDK 1.0.0-alpha.19+, this verifier tries both keys.
 *
 * Usage:
 *   node polar-webhook-verify.js <webhook-payload-json> [webhook-secret]
 *
 * Environment Variables:
 *   POLAR_WEBHOOK_SECRET - Webhook secret exactly as shown in the Polar dashboard
 */

const crypto = require('crypto');

const TOLERANCE_SECONDS = 5 * 60;
const WHSEC_PREFIX = 'whsec_';

function decodeBase64Strict(value) {
  const unpadded = value.replace(/=+$/, '');
  if (!/^[A-Za-z0-9+/]*={0,2}$/.test(value) || unpadded.length % 4 === 1) {
    return null;
  }
  return Buffer.from(value, 'base64');
}

class PolarWebhookVerifier {
  constructor(secret) {
    if (!secret) {
      throw new Error('Webhook secret is required');
    }
    this.secret = secret;
    this.keys = PolarWebhookVerifier.signingKeys(secret);
  }

  /**
   * Candidate HMAC keys: legacy Polar HMAC first, then Standard Webhooks.
   */
  static signingKeys(secret) {
    const utf8Key = Buffer.from(secret, 'utf8');
    const keys = [utf8Key];
    const remainder = secret.startsWith(WHSEC_PREFIX) ? secret.slice(WHSEC_PREFIX.length) : secret;
    const decoded = decodeBase64Strict(remainder);
    if (decoded && decoded.length > 0 && !decoded.equals(utf8Key)) {
      keys.push(decoded);
    }
    return keys;
  }

  static computeSignature(key, webhookId, timestamp, payload) {
    return crypto
      .createHmac('sha256', key)
      .update(`${webhookId}.${timestamp}.${payload}`)
      .digest('base64');
  }

  /**
   * Build signed headers for local testing (scheme: 'standard' | 'legacy').
   */
  static sign(payload, secret, { webhookId, timestamp, scheme = 'standard' } = {}) {
    const keys = PolarWebhookVerifier.signingKeys(secret);
    const key = scheme === 'legacy' || keys.length === 1 ? keys[0] : keys[1];
    const id = webhookId || `msg_${crypto.randomUUID()}`;
    const ts = String(timestamp || Math.floor(Date.now() / 1000));
    const body = Buffer.isBuffer(payload) ? payload.toString('utf8') : payload;
    return {
      'webhook-id': id,
      'webhook-timestamp': ts,
      'webhook-signature': `v1,${PolarWebhookVerifier.computeSignature(key, id, ts, body)}`
    };
  }

  /**
   * Verify webhook signature against the RAW request body (string or Buffer).
   */
  verifySignature(payload, headers) {
    if (typeof payload !== 'string' && !Buffer.isBuffer(payload)) {
      throw new Error('Raw request body (string or Buffer) is required');
    }
    const body = Buffer.isBuffer(payload) ? payload.toString('utf8') : payload;

    const normalized = {};
    for (const [key, value] of Object.entries(headers || {})) {
      normalized[key.toLowerCase()] = Array.isArray(value) ? value.join(' ') : value;
    }
    const webhookId = normalized['webhook-id'];
    const webhookTimestamp = normalized['webhook-timestamp'];
    const webhookSignature = normalized['webhook-signature'];

    if (!webhookId || !webhookTimestamp || !webhookSignature) {
      throw new Error('Missing required webhook headers');
    }

    const timestamp = Number(webhookTimestamp);
    if (!Number.isFinite(timestamp)) {
      throw new Error('Invalid webhook-timestamp header');
    }
    const now = Math.floor(Date.now() / 1000);
    if (Math.abs(now - timestamp) > TOLERANCE_SECONDS) {
      throw new Error('Webhook timestamp too old or in future');
    }

    const expected = this.keys.map(key =>
      Buffer.from(PolarWebhookVerifier.computeSignature(key, webhookId, Math.floor(timestamp), body), 'base64')
    );

    for (const entry of webhookSignature.split(' ')) {
      const commaIndex = entry.indexOf(',');
      if (commaIndex === -1 || entry.slice(0, commaIndex) !== 'v1') continue;
      const provided = decodeBase64Strict(entry.slice(commaIndex + 1));
      if (!provided) continue;
      for (const candidate of expected) {
        if (provided.length === candidate.length && crypto.timingSafeEqual(provided, candidate)) {
          return true;
        }
      }
    }

    throw new Error('Invalid webhook signature');
  }

  /**
   * Verify and parse a webhook event
   */
  process(payload, headers) {
    try {
      this.verifySignature(payload, headers);

      const event = JSON.parse(Buffer.isBuffer(payload) ? payload.toString('utf8') : payload);

      if (!event.type || !event.data) {
        throw new Error('Invalid event structure');
      }

      return {
        success: true,
        event: {
          type: event.type,
          timestamp: event.timestamp,
          apiVersion: event.api_version,
          data: event.data
        }
      };
    } catch (error) {
      return {
        success: false,
        error: error.message
      };
    }
  }

  /**
   * Get event category
   */
  static getEventCategory(eventType) {
    const categories = {
      'checkout.': 'checkout',
      'order.': 'order',
      'subscription.': 'subscription',
      'customer_seat.': 'seat',
      'customer.': 'customer',
      'benefit_grant.': 'benefit_grant',
      'benefit.': 'benefit',
      'refund.': 'refund',
      'product.': 'product',
      'discount.': 'discount',
      'member.': 'member',
      'organization.': 'organization'
    };

    for (const [prefix, category] of Object.entries(categories)) {
      if (eventType.startsWith(prefix)) {
        return category;
      }
    }

    return 'unknown';
  }

  /**
   * Payment collected. order.created can still be pending (e.g. renewals).
   */
  static isPaymentEvent(eventType) {
    return eventType === 'order.paid';
  }

  /**
   * Check if event is a subscription change
   */
  static isSubscriptionEvent(eventType) {
    return eventType.startsWith('subscription.');
  }
}

// CLI Usage
if (require.main === module) {
  const args = process.argv.slice(2);

  if (args.length < 1) {
    console.log('Usage: node polar-webhook-verify.js <webhook-payload-json> [webhook-secret]');
    console.log('\nWebhook secret can also be provided via POLAR_WEBHOOK_SECRET environment variable');
    console.log('\nExample:');
    console.log('  node polar-webhook-verify.js \'{"type":"order.paid","data":{...}}\' whsec_xxx');
    process.exit(1);
  }

  try {
    const payload = args[0];
    const secret = args[1] || process.env.POLAR_WEBHOOK_SECRET;

    if (!secret) {
      console.error('✗ Error: Webhook secret is required');
      console.error('Provide it as second argument or set POLAR_WEBHOOK_SECRET environment variable');
      process.exit(1);
    }

    // Self-test: sign locally, then verify
    const headers = PolarWebhookVerifier.sign(payload, secret);
    const verifier = new PolarWebhookVerifier(secret);
    const result = verifier.process(payload, headers);

    if (result.success) {
      console.log('✓ Webhook verified successfully\n');
      console.log('Event Details:');
      console.log(`  Type: ${result.event.type}`);
      console.log(`  Category: ${PolarWebhookVerifier.getEventCategory(result.event.type)}`);
      console.log(`  Is Payment: ${PolarWebhookVerifier.isPaymentEvent(result.event.type) ? 'Yes' : 'No'}`);
      console.log(`  Is Subscription: ${PolarWebhookVerifier.isSubscriptionEvent(result.event.type) ? 'Yes' : 'No'}`);
      console.log('\nEvent Data:');
      console.log(JSON.stringify(result.event.data, null, 2));
    } else {
      console.error('✗ Verification failed:', result.error);
      process.exit(1);
    }
  } catch (error) {
    console.error('✗ Error:', error.message);
    process.exit(1);
  }
}

module.exports = PolarWebhookVerifier;
